  /* --------------------------------------------------------------------------
   * 2. 이미지 프리로딩 & Canvas 원형/컷인 초상화 정밀 크롭 헬퍼
   * -------------------------------------------------------------------------- */
  const loadedImgCache = {};
  function getWarlordImageObj(id) {
    if (loadedImgCache[id]) return loadedImgCache[id];
    const info = WARLORD_PORTRAITS[id] || WARLORD_PORTRAITS.liubei;
    const im = new Image();
    im.onerror = () => {
      if (im.src !== info.data) im.src = info.data;
    };
    im.src = info.file;
    loadedImgCache[id] = im;
    return im;
  }

  // 초기 로드 시 6대 군주 이미지 모두 백그라운드 프리로드
  WARLORDS.forEach(w => getWarlordImageObj(w.id));

  function getPortraitSrc(id) {
    const info = WARLORD_PORTRAITS[id] || WARLORD_PORTRAITS.liubei;
    const cached = loadedImgCache[id];
    if (cached && cached.complete && cached.naturalWidth > 0) return cached.src;
    return info.data;
  }

  function getPortraitFallbackAttr(id) {
    const info = WARLORD_PORTRAITS[id] || WARLORD_PORTRAITS.liubei;
    return `onerror="this.onerror=null;this.src='${info.data}'"`;
  }

  function getPortraitPos(id) {
    const info = WARLORD_PORTRAITS[id] || WARLORD_PORTRAITS.liubei;
    return info.crop ? info.crop.pos : '50% 25%';
  }

  // Canvas 위에 군주 초상화를 얼굴 중심 자동 크롭으로 깔끔하게 원형 렌더링
  function drawWarlordPortraitOnCanvas(ctx, id, x, y, r, borderColor, glowColor, alpha = 1) {
    const im = getWarlordImageObj(id);
    const info = WARLORD_PORTRAITS[id] || WARLORD_PORTRAITS.liubei;
    const crop = info.crop || { cx: 0.5, cy: 0.38, zoom: 1.15 };

    ctx.save();
    ctx.globalAlpha = alpha;
    if (glowColor) {
      ctx.shadowColor = glowColor;
      ctx.shadowBlur = Math.max(14, r * 0.45);
    }

    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fillStyle = '#0f172a';
    ctx.fill();

    if (im && im.complete && im.naturalWidth > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.clip();

      const iw = im.naturalWidth;
      const ih = im.naturalHeight;
      const baseSide = Math.min(iw, ih) / crop.zoom;
      let sx = iw * crop.cx - baseSide * 0.5;
      let sy = ih * crop.cy - baseSide * 0.5;
      sx = Math.max(0, Math.min(iw - baseSide, sx));
      sy = Math.max(0, Math.min(ih - baseSide, sy));

      ctx.drawImage(im, sx, sy, baseSide, baseSide, x - r, y - r, r * 2, r * 2);
      ctx.restore();
    }

    if (borderColor) {
      ctx.shadowBlur = 0;
      ctx.strokeStyle = borderColor;
      ctx.lineWidth = Math.max(2.5, r * 0.08);
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }

  const getWarlord = (id) => WARLORDS.find(w => w.id === id) || WARLORDS[0];
  const savedId = () => {
    try { return localStorage.getItem('jg_selected_warlord') || 'liubei'; } catch (e) { return 'liubei'; }
  };

  window.JG_WARLORDS = WARLORDS;
  window.JG_MY_WARLORD = savedId();
  window.JG_OPP_WARLORD = 'caocao';
  window.__JG_WARLORD_MATCH_READY__ = false;
  window.__JG_WARLORD_ACT_USED__ = false;
  window.__JG_WARLORD_SHOUT_CD__ = 0;
  const generalQuoteIndex = {};

  function pickNextGeneralQuote(w) {
    const list = w.generalQuotes || [];
    if (!list.length) return null;
    const idx = generalQuoteIndex[w.id] || 0;
    generalQuoteIndex[w.id] = (idx + 1) % list.length;
    return list[idx];
  }

  /* --------------------------------------------------------------------------
   * 3. Web Audio API 군주 전용 효과음 합성기
   * -------------------------------------------------------------------------- */
  function playWarlordSfx(type) {
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      const ac = window.__JG_WL_AC || (window.__JG_WL_AC = new Ctx());
      if (ac.state === 'suspended') ac.resume();
      const now = ac.currentTime;

      const osc = ac.createOscillator();
      const gain = ac.createGain();
      if (type === 'select') {
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(340, now);
        osc.frequency.exponentialRampToValueAtTime(680, now + 0.14);
        gain.gain.setValueAtTime(0.16, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
        osc.connect(gain); gain.connect(ac.destination);
        osc.start(now); osc.stop(now + 0.19);
      } else if (type === 'action' || type === 'check') {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(145, now);
        osc.frequency.exponentialRampToValueAtTime(42, now + 0.58);
        gain.gain.setValueAtTime(0.25, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.62);
        osc.connect(gain); gain.connect(ac.destination);
        osc.start(now); osc.stop(now + 0.64);

        const osc2 = ac.createOscillator();
        const gain2 = ac.createGain();
        osc2.type = 'sine';
        osc2.frequency.setValueAtTime(540, now + 0.04);
        osc2.frequency.exponentialRampToValueAtTime(920, now + 0.36);
        gain2.gain.setValueAtTime(0.14, now + 0.04);
        gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.44);
        osc2.connect(gain2); gain2.connect(ac.destination);
        osc2.start(now + 0.04); osc2.stop(now + 0.46);
      }
    } catch (e) {}
  }

